// src/pages/AdminProductsPage.js
import React, { useEffect, useState } from 'react';
import { BACKEND_URL } from '../services/api';

export default function AdminProductsPage() {
  // Mostrar u ocultar el formulario de creación
  const [showCreateForm, setShowCreateForm] = useState(false);

  // Estados para el formulario de creación de producto
  const [newName, setNewName] = useState('');
  const [newDescription, setNewDescription] = useState('');
  const [newPrice, setNewPrice] = useState('');
  const [newStock, setNewStock] = useState('');
  const [newCategoryId, setNewCategoryId] = useState('');
  const [newBrandId, setNewBrandId] = useState('');
  const [newBarcode, setNewBarcode] = useState('');
  const [newImageFile, setNewImageFile] = useState(null);
  const [useVariants, setUseVariants] = useState(false);
  const [newVariantsText, setNewVariantsText] = useState('');
  // Estado para el local del producto (default "1")
  const [newLocalId, setNewLocalId] = useState('1');

  // Estados para datos de apoyo: categorías, marcas y locales
  const [categories, setCategories] = useState([]);
  const [brands, setBrands] = useState([]);
  const [locales, setLocales] = useState([]);

  // Estado para recargar el listado y para edición
  const [reloadKey, setReloadKey] = useState(0);
  const [editProduct, setEditProduct] = useState(null);

  useEffect(() => {
    loadCategories();
    loadBrands();
    loadLocales();
  }, []);

  const loadCategories = async () => {
    try {
      const resp = await fetch(
        `${BACKEND_URL}/categories?limit=99999&offset=0&order=name:asc`
      );
      const data = await resp.json();
      setCategories(data);
    } catch (error) {
      console.error("Error cargando categorías:", error);
    }
  };

  const loadBrands = async () => {
    try {
      const resp = await fetch(
        `${BACKEND_URL}/brands?limit=99999&offset=0&order=name:asc`
      );
      const data = await resp.json();
      setBrands(data);
    } catch (error) {
      console.error("Error cargando marcas:", error);
    }
  };

  const loadLocales = async () => {
    try {
      const resp = await fetch(
        `${BACKEND_URL}/locals?limit=99999&offset=0&order=name:asc`
      );
      const data = await resp.json();
      setLocales(data);
    } catch (error) {
      console.error("Error cargando locales:", error);
    }
  };

  const handleCreateProduct = async (e) => {
    e.preventDefault();
    if (!newImageFile) {
      alert("Selecciona una imagen");
      return;
    }
    // Usamos FileReader para obtener la imagen en base64 (podrías usar convertToWebp si lo requieres)
    const reader = new FileReader();
    reader.onload = async (ev) => {
      try {
        const base64 = ev.target.result;
        // Armamos el payload para la creación
        let payload = {
          name: newName,
          description: newDescription,
          price: parseFloat(newPrice),
          barcode: newBarcode,
          // Si se usan variantes, se parsean; de lo contrario, se asigna stock
          variants: [],
          categoryId: newCategoryId,
          brandId: newBrandId,
          localId: newLocalId ? parseInt(newLocalId) : 1,
          image: base64,
        };
        if (useVariants && newVariantsText.trim()) {
          const lines = newVariantsText.split('\n');
          payload.variants = lines.map((line) => {
            const [color, st] = line.split('|');
            return { color: color.trim(), stock: parseInt(st.trim() || '0') };
          });
        } else {
          payload.stock = parseInt(newStock);
        }
        await fetch(`${BACKEND_URL}/products`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
        // Reiniciamos los campos del formulario
        setNewName('');
        setNewDescription('');
        setNewPrice('');
        setNewStock('');
        setNewCategoryId('');
        setNewBrandId('');
        setNewBarcode('');
        setNewImageFile(null);
        setUseVariants(false);
        setNewVariantsText('');
        setNewLocalId('1');
        setReloadKey(reloadKey + 1);
        setShowCreateForm(false);
      } catch (error) {
        console.error("Error creando producto:", error);
      }
    };
    reader.readAsDataURL(newImageFile);
  };

  const handleDeleteProduct = async (id) => {
    if (!window.confirm("¿Está seguro de eliminar este producto?")) return;
    try {
      await fetch(`${BACKEND_URL}/products/${id}`, { method: 'DELETE' });
      setReloadKey(reloadKey + 1);
    } catch (error) {
      console.error("Error eliminando producto:", error);
    }
  };

  async function handleUpdateProduct(updatedProduct, file) {
    // Armamos el payload para actualizar
    let payload = {
      name: updatedProduct.name,
      description: updatedProduct.description,
      price: parseFloat(updatedProduct.price),
      barcode: updatedProduct.barcode,
      categoryId: updatedProduct.categoryId,
      brandId: updatedProduct.brandId,
      localId: updatedProduct.localId ? parseInt(updatedProduct.localId) : 1,
      variants: [],
    };
    if (updatedProduct.variants && updatedProduct.variants.length > 0) {
      payload.variants = updatedProduct.variants;
    } else {
      payload.stock = parseInt(updatedProduct.stock);
    }
    if (file) {
      const reader = new FileReader();
      reader.onload = async (ev) => {
        try {
          const base64 = ev.target.result;
          payload.image = base64;
          await fetch(`${BACKEND_URL}/products/${updatedProduct.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload),
          });
          setReloadKey(reloadKey + 1);
          setEditProduct(null);
        } catch (error) {
          console.error("Error actualizando producto:", error);
        }
      };
      reader.readAsDataURL(file);
    } else {
      await fetch(`${BACKEND_URL}/products/${updatedProduct.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
      });
      setReloadKey(reloadKey + 1);
      setEditProduct(null);
    }
  }

  return (
    <div className="container mt-3">
      <h3>Gestión de Productos</h3>

      {/* Botón para mostrar/ocultar formulario de creación */}
      <div className="mb-3">
        <button
          className="btn btn-primary"
          onClick={() => setShowCreateForm(!showCreateForm)}
        >
          {showCreateForm ? 'Cerrar Formulario' : 'Agregar Nuevo Producto'}
        </button>
      </div>

      {/* Formulario de creación */}
      {showCreateForm && (
        <form onSubmit={handleCreateProduct} className="card p-3 mb-4">
          <h5>Nuevo Producto</h5>
          <div className="form-group">
            <label>Nombre</label>
            <input
              type="text"
              className="form-control"
              value={newName}
              onChange={(e) => setNewName(e.target.value)}
              required
            />
          </div>
          <div className="form-group">
            <label>Descripción</label>
            <textarea
              className="form-control"
              value={newDescription}
              onChange={(e) => setNewDescription(e.target.value)}
            />
          </div>

          <div className="form-row">
            <div className="form-group col-md-3">
              <label>Precio</label>
              <input
                type="number"
                className="form-control"
                value={newPrice}
                onChange={(e) => setNewPrice(e.target.value)}
                required
              />
            </div>
            <div className="form-group col-md-3">
              <label>Stock (sin variantes)</label>
              <input
                type="number"
                className="form-control"
                value={newStock}
                disabled={useVariants}
                onChange={(e) => setNewStock(e.target.value)}
                required={!useVariants}
              />
            </div>
            <div className="form-group col-md-3">
              <label>Categoría</label>
              <select
                className="form-control"
                value={newCategoryId}
                onChange={(e) => setNewCategoryId(e.target.value)}
                required
              >
                <option value="">Seleccionar...</option>
                {categories.map((c) => (
                  <option key={c.id} value={c.id}>
                    {c.name}
                  </option>
                ))}
              </select>
            </div>
            <div className="form-group col-md-3">
              <label>Marca</label>
              <select
                className="form-control"
                value={newBrandId}
                onChange={(e) => setNewBrandId(e.target.value)}
                required
              >
                <option value="">Seleccionar...</option>
                {brands
                  .filter((b) => b.categoryId === newCategoryId)
                  .map((b) => (
                    <option key={b.id} value={b.id}>
                      {b.name}
                    </option>
                  ))}
              </select>
            </div>
          </div>

          <div className="form-row">
            <div className="form-group col-md-4">
              <label>Código de Barras</label>
              <input
                type="text"
                className="form-control"
                value={newBarcode}
                onChange={(e) => setNewBarcode(e.target.value)}
              />
            </div>
            <div className="form-group col-md-4">
              <label>Local</label>
              <select
                className="form-control"
                value={newLocalId}
                onChange={(e) => setNewLocalId(e.target.value)}
              >
                <option value="1">Local 1</option>
                {locales.map((l) => (
                  <option key={l.id} value={l.id}>
                    {l.name}
                  </option>
                ))}
              </select>
            </div>
            <div className="form-group col-md-4">
              <label>Imagen</label>
              <input
                type="file"
                accept="image/*"
                className="form-control-file"
                onChange={(e) => setNewImageFile(e.target.files[0])}
                required
              />
            </div>
          </div>

          {/* Checkbox “usar variantes” */}
          <div className="form-check mb-2">
            <input
              type="checkbox"
              className="form-check-input"
              id="useVariantsCheck"
              checked={useVariants}
              onChange={(e) => setUseVariants(e.target.checked)}
            />
            <label className="form-check-label" htmlFor="useVariantsCheck">
              ¿Usar variantes (color/talla)?
            </label>
          </div>
          {useVariants && (
            <div className="form-group">
              <label>Variantes (Color|Stock, uno por línea)</label>
              <textarea
                className="form-control"
                value={newVariantsText}
                onChange={(e) => setNewVariantsText(e.target.value)}
                placeholder="Rojo|10&#10;Verde|20"
              />
            </div>
          )}

          <button type="submit" className="btn btn-success">
            Guardar
          </button>
        </form>
      )}

      <h4>Productos</h4>
      {/* ProductSearch: lista y búsqueda de productos */}
      <ProductSearch
        reloadKey={reloadKey}
        onEdit={(prod) => setEditProduct(prod)}
        onDelete={(id) => handleDeleteProduct(id)}
        locales={locales}
      />

      {/* Modal de edición */}
      {editProduct && (
        <EditProductModal
          product={editProduct}
          categories={categories}
          brands={brands}
          locales={locales}
          onClose={() => setEditProduct(null)}
          onUpdate={handleUpdateProduct}
        />
      )}
    </div>
  );
}

/* --------------------- MODAL DE EDICIÓN --------------------- */
function EditProductModal({ product, categories, brands, locales, onClose, onUpdate }) {
  const [name, setName] = useState(product.name);
  const [description, setDescription] = useState(product.description || '');
  const [price, setPrice] = useState(product.price);
  const [stock, setStock] = useState(product.stock);
  const [categoryId, setCategoryId] = useState(product.categoryId);
  const [brandId, setBrandId] = useState(product.brandId);
  const [barcode, setBarcode] = useState(product.barcode || '');
  const [localId, setLocalId] = useState(product.localId ? product.localId.toString() : '1');
  const [file, setFile] = useState(null);

  // Parsear variants inicial (si existen)
  let initialVariants = [];
  if (product.variantsJson) {
    try {
      initialVariants = JSON.parse(product.variantsJson);
    } catch {}
  }
  const [useVariants, setUseVariants] = useState(initialVariants.length > 0);
  const [variantsText, setVariantsText] = useState(() => {
    if (initialVariants.length > 0) {
      return initialVariants.map(v => `${v.color}|${v.stock}`).join('\n');
    }
    return '';
  });

  function handleSubmit(e) {
    e.preventDefault();
    let variantsArr = [];
    if (useVariants && variantsText.trim()) {
      const lines = variantsText.split('\n');
      for (let line of lines) {
        const [color, st] = line.split('|');
        variantsArr.push({
          color: color?.trim() || '',
          stock: parseInt(st || '0')
        });
      }
    }
    const updated = {
      ...product,
      name,
      description,
      price: parseFloat(price),
      categoryId,
      brandId,
      barcode,
      localId: localId ? parseInt(localId) : 1,
    };
    if (useVariants && variantsArr.length > 0) {
      updated.variants = variantsArr;
    } else {
      updated.stock = parseInt(stock);
      updated.variants = [];
    }
    onUpdate(updated, file);
  }

  return (
    <div
      className="modal"
      style={{ display: 'block', background: 'rgba(0,0,0,0.4)' }}
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content custom-modal">
          <div className="modal-header">
            <h5 className="modal-title">Editar Producto</h5>
            <button className="close" onClick={onClose}>×</button>
          </div>
          <div className="modal-body">
            <form onSubmit={handleSubmit}>
              {/* Nombre, Precio y Local */}
              <div className="form-row">
                <div className="form-group col-md-4">
                  <label>Nombre</label>
                  <input
                    type="text"
                    className="form-control"
                    value={name}
                    onChange={(e) => setName(e.target.value)}
                    required
                  />
                </div>
                <div className="form-group col-md-4">
                  <label>Precio</label>
                  <input
                    type="number"
                    className="form-control"
                    value={price}
                    onChange={(e) => setPrice(e.target.value)}
                    required
                  />
                </div>
                <div className="form-group col-md-4">
                  <label>Local</label>
                  <select
                    className="form-control"
                    value={localId}
                    onChange={(e) => setLocalId(e.target.value)}
                  >
                    <option value="1">Local 1</option>
                    {locales.map(l => (
                      <option key={l.id} value={l.id}>
                        {l.name}
                      </option>
                    ))}
                  </select>
                </div>
              </div>
              {/* Descripción */}
              <div className="form-group">
                <label>Descripción</label>
                <textarea
                  className="form-control"
                  value={description}
                  onChange={(e) => setDescription(e.target.value)}
                />
              </div>
              {/* Stock / Categoría / Marca / Código */}
              <div className="form-row">
                <div className="form-group col-md-3">
                  <label>Stock</label>
                  <input
                    type="number"
                    className="form-control"
                    value={stock}
                    disabled={useVariants}
                    onChange={(e) => setStock(e.target.value)}
                    required={!useVariants}
                  />
                </div>
                <div className="form-group col-md-3">
                  <label>Categoría</label>
                  <select
                    className="form-control"
                    value={categoryId}
                    onChange={(e) => {
                      setCategoryId(e.target.value);
                      setBrandId(''); // Resetea marca
                    }}
                    required
                  >
                    {categories.map((c) => (
                      <option key={c.id} value={c.id}>
                        {c.name}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="form-group col-md-3">
                  <label>Marca</label>
                  <select
                    className="form-control"
                    value={brandId}
                    onChange={(e) => setBrandId(e.target.value)}
                    required
                  >
                    {brands
                      .filter((b) => b.categoryId === categoryId)
                      .map((b) => (
                        <option key={b.id} value={b.id}>
                          {b.name}
                        </option>
                      ))}
                  </select>
                </div>
                <div className="form-group col-md-3">
                  <label>Código de barras</label>
                  <input
                    type="text"
                    className="form-control"
                    value={barcode}
                    onChange={(e) => setBarcode(e.target.value)}
                  />
                </div>
              </div>
              {/* Checkbox para usar variantes */}
              <div className="form-check mb-2">
                <input
                  type="checkbox"
                  className="form-check-input"
                  id="editUseVariantsCheck"
                  checked={useVariants}
                  onChange={(e) => setUseVariants(e.target.checked)}
                />
                <label htmlFor="editUseVariantsCheck" className="form-check-label">
                  ¿Usar variantes (color/talla)?
                </label>
              </div>
              {useVariants && (
                <div className="form-group">
                  <label>Variantes (Color|Stock)</label>
                  <textarea
                    className="form-control"
                    value={variantsText}
                    onChange={(e) => setVariantsText(e.target.value)}
                  />
                </div>
              )}
              {/* Imagen (opcional) */}
              <div className="form-group">
                <label>Imagen</label>
                <input
                  type="file"
                  accept="image/*"
                  className="form-control-file"
                  onChange={(e) => setFile(e.target.files[0])}
                />
              </div>
              {product.image && (
                <div className="text-center mb-2">
                  <img
                    src={product.image}
                    alt={product.name}
                    style={{ width: 100, height: 100, objectFit: 'cover' }}
                  />
                </div>
              )}
              {/* Botones */}
              <div className="modal-footer">
                <button type="submit" className="btn btn-success">
                  Actualizar
                </button>
                <button type="button" className="btn btn-secondary" onClick={onClose}>
                  Cancelar
                </button>
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------------------------------------------
   Componente Reutilizable: ProductSearch (listar y buscar productos)
   ------------------------------------------------------------------ */
function ProductSearch({
  reloadKey = 0,
  limit = 10,
  onEdit,
  onDelete,
  locales,
}) {
  const [page, setPage] = useState(0);
  const [searchTerm, setSearchTerm] = useState('');
  const [products, setProducts] = useState([]);

  // Recarga cada vez que cambie page, searchTerm o reloadKey
  useEffect(() => {
    loadData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [page, searchTerm, reloadKey]);

  async function loadData() {
    try {
      const offset = page * limit;
      let url = `${BACKEND_URL}/products?limit=${limit}&offset=${offset}&order=name:asc`;
      if (searchTerm.trim()) {
        url += `&searchTerm=${encodeURIComponent(searchTerm.trim())}`;
      }
      const resp = await fetch(url);
      const data = await resp.json();
      if (data.length === 0 && page > 0) {
        setPage(Math.max(0, page - 1));
        return;
      }
      setProducts(data);
    } catch (error) {
      console.error("Error en ProductSearch loadData:", error);
    }
  }

  function handleEditClick(prod) {
    if (onEdit) onEdit(prod);
  }
  function handleDeleteClick(id) {
    if (onDelete) onDelete(id);
  }

  return (
    <div style={{ border: '1px solid #ccc', padding: '10px', borderRadius: '6px' }}>
      <h5>Listado / Búsqueda de Productos</h5>
      {/* Buscador */}
      <div className="form-group mb-2">
        <input
          type="text"
          className="form-control"
          placeholder="Buscar en el servidor..."
          value={searchTerm}
          onChange={(e) => {
            setPage(0);
            setSearchTerm(e.target.value);
          }}
        />
      </div>
      <table className="table table-bordered table-sm">
        <thead>
          <tr>
            <th>Nombre</th>
            <th>Precio</th>
            <th>Stock</th>
            <th>Código</th>
            <th>Local</th>
            <th>Acciones</th>
          </tr>
        </thead>
        <tbody>
          {products.map((p) => {
            const loc = locales.find(l => l.id === p.localId);
            return (
              <tr key={p.id}>
                <td>{p.name}</td>
                <td>${p.price}</td>
                <td>{p.stock}</td>
                <td>{p.barcode}</td>
                <td>{loc ? loc.name : 'Local 1 (por defecto)'}</td>
                <td>
                  <button className="btn btn-primary btn-sm mr-1" onClick={() => handleEditClick(p)}>
                    Editar
                  </button>
                  <button className="btn btn-danger btn-sm" onClick={() => handleDeleteClick(p.id)}>
                    Eliminar
                  </button>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {/* Paginación */}
      <div className="d-flex justify-content-between">
        <button
          className="btn btn-secondary btn-sm"
          onClick={() => setPage(Math.max(0, page - 1))}
        >
          Anterior
        </button>
        <button
          className="btn btn-secondary btn-sm"
          onClick={() => setPage(page + 1)}
        >
          Siguiente
        </button>
      </div>
    </div>
  );
}
